"""--work on normalize and look: every clip is generated by tests/media.py inside tmp_path, never real footage."""

import json

import pytest
from media import make_clip, make_manifest, sha256

import v2r.look
import v2r.normalize
from v2r import settings
from v2r.__main__ import main

SMALL_CAPS = {
    "tall": {"portrait": (180, 320), "landscape": (None, 320)},
    "wide": {"landscape": (320, 180), "portrait": (320, None)},
}
CLIP_SIZE = {"tall": (360, 640), "wide": (640, 360)}  # the clip sizes swap with the shape


@pytest.fixture
def small_caps(monkeypatch):
    """Small working sizes, so test clips stay tiny and the two shapes still give different sizes."""
    monkeypatch.setattr(settings, "WORKING_SIZE", SMALL_CAPS)


@pytest.fixture
def default_work(tmp_path, monkeypatch):
    """Send the default work folder into tmp_path, so a slip never touches this repo's work/; returns that folder."""
    folder = tmp_path / "default-work"
    monkeypatch.setattr(v2r.normalize, "WORK_DIR", folder)
    monkeypatch.setattr(v2r.look, "WORK_DIR", folder)
    return folder


def sent_clip(tmp_path, name="in.mp4", seconds=4):
    (tmp_path / "sent").mkdir(exist_ok=True)
    return make_clip(tmp_path / "sent" / name, 640, 360, seconds=seconds)


def look_folder(tmp_path, name, shape):
    """A work folder holding clip A and its manifest, made without running normalize."""
    folder = tmp_path / name
    folder.mkdir()
    width, height = CLIP_SIZE[shape]
    make_clip(folder / "A.mp4", width, height, seconds=4)
    make_manifest(folder, shape, [folder / "A.mp4"])
    return folder


def snapshot(folder):
    """Every file under `folder` with its sha256."""
    return {str(path.relative_to(folder)): sha256(path) for path in sorted(folder.rglob("*")) if path.is_file()}


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_tracer_work_folder_through_normalize_and_look(shape, tmp_path, small_caps, default_work):
    clip = sent_clip(tmp_path)
    folder = tmp_path / "set-one"

    assert main(["normalize", "--shape", shape, "--work", str(folder), str(clip)]) == 0

    assert (folder / "A.mp4").exists(), "the working copy should be in the --work folder"
    manifest = json.loads((folder / "manifest.json").read_text(encoding="utf-8"))
    assert manifest["shape"] == shape

    assert main(["look", "--work", str(folder)]) == 0

    look = json.loads((folder / "look.json").read_text(encoding="utf-8"))
    assert [c["letter"] for c in look["clips"]] == ["A"]
    assert list((folder / "sheets").glob("*.jpg")), "look should have made at least one sheet"
    assert not default_work.exists(), "the default work folder must stay untouched"


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_normalize_work_after_the_files(shape, tmp_path, small_caps, default_work):
    clip = sent_clip(tmp_path)
    folder = tmp_path / "set-one"

    assert main(["normalize", "--shape", shape, str(clip), "--work", str(folder)]) == 0

    assert (folder / "A.mp4").exists()
    assert (folder / "manifest.json").exists()
    assert not default_work.exists()


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_two_work_folders_side_by_side(shape, tmp_path, small_caps, default_work):
    clip = sent_clip(tmp_path)
    one, two = tmp_path / "set-one", tmp_path / "set-two"

    assert main(["normalize", "--shape", shape, "--work", str(one), str(clip)]) == 0
    before = snapshot(one)
    assert main(["normalize", "--shape", shape, "--work", str(two), str(clip)]) == 0

    assert before and snapshot(one) == before, "the second run must leave the first folder unchanged"
    assert (two / "A.mp4").exists()


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_normalize_work_clears_only_that_folders_last_job(shape, tmp_path, small_caps, default_work):
    first = sent_clip(tmp_path, "first.mp4", seconds=2)
    second = sent_clip(tmp_path, "second.mp4", seconds=2)
    folder = tmp_path / "set-one"

    assert main(["normalize", "--shape", shape, "--work", str(folder), str(first), str(second)]) == 0
    assert (folder / "B.mp4").exists()
    (folder / "notes.txt").write_text("keep me", encoding="utf-8")
    old_manifest = (folder / "manifest.json").read_bytes()

    assert main(["normalize", "--shape", shape, "--work", str(folder), str(first)]) == 0

    assert not (folder / "B.mp4").exists(), "the last job's second copy should be cleared"
    assert (folder / "A.mp4").exists()
    assert (folder / "manifest.json").read_bytes() != old_manifest
    assert len(json.loads((folder / "manifest.json").read_text(encoding="utf-8"))["clips"]) == 1
    assert (folder / "notes.txt").read_text(encoding="utf-8") == "keep me", "a file that is not a working copy stays"


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_normalize_work_leaves_an_original_inside_it_alone(shape, tmp_path, small_caps, default_work, capsys):
    folder = tmp_path / "set-one"
    folder.mkdir()
    original = make_clip(folder / "in.mp4", 640, 360, seconds=2)
    before = sha256(original)

    assert main(["normalize", "--shape", shape, "--work", str(folder), str(original)]) == 1

    out = capsys.readouterr()
    assert "already in the work folder" in out.out + out.err
    assert original.exists() and sha256(original) == before


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_look_folder_and_work_option_agree(shape, tmp_path):
    positional = look_folder(tmp_path, "by-position", shape)
    optional = look_folder(tmp_path, "by-option", shape)

    assert main(["look", str(positional)]) == 0
    assert main(["look", "--work", str(optional)]) == 0

    def letters_and_sheets(folder):
        look = json.loads((folder / "look.json").read_text(encoding="utf-8"))
        return [c["letter"] for c in look["clips"]], sorted(p.name for p in (folder / "sheets").iterdir())

    assert letters_and_sheets(positional) == letters_and_sheets(optional)


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_look_folder_named_twice_differently_is_refused(shape, tmp_path, capsys):
    one = look_folder(tmp_path, "one", shape)
    two = look_folder(tmp_path, "two", shape)

    assert main(["look", str(one), "--work", str(two)]) == 1

    lines = [line for line in capsys.readouterr().err.splitlines() if line.strip()]
    assert len(lines) == 1 and lines[0].startswith("v2r look:")
    assert not (one / "look.json").exists() and not (two / "look.json").exists()


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_look_folder_named_twice_the_same_is_fine(shape, tmp_path):
    folder = look_folder(tmp_path, "one", shape)

    assert main(["look", str(folder), "--work", str(folder)]) == 0
    assert (folder / "look.json").exists()


def stub_job(folder, shape, listed, unlisted):
    """A work folder a past job left: `listed` names have a manifest entry, `unlisted` ones are lettered files it never made."""
    folder.mkdir()
    entries = []
    for number, name in enumerate(listed, start=1):
        (folder / name).write_bytes(b"old working copy")
        working = {"file": name, "size": [2, 2], "fps": 30.0, "seconds": 1.0, "bytes": 16,
                   "sound_added": False, "colour_converted": False}
        entries.append({"file": folder / name, "working": working})
    make_manifest(folder, shape, entries)
    for name in unlisted:
        (folder / name).write_bytes(b"not made by this job")


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_work_folder_with_a_stray_lettered_file_and_no_manifest_is_refused(shape, tmp_path, small_caps, default_work, capsys):
    clip = sent_clip(tmp_path)
    folder = tmp_path / "my-own-media"
    folder.mkdir()
    (folder / "A.mp4").write_bytes(b"someone's own video")
    (folder / "notes.txt").write_bytes(b"keep")
    before = snapshot(folder)

    assert main(["normalize", "--shape", shape, "--work", str(folder), str(clip)]) == 1

    lines = [line for line in capsys.readouterr().err.splitlines() if line.strip()]
    assert len(lines) == 1 and lines[0].startswith("v2r normalize:") and "no manifest.json" in lines[0]
    assert snapshot(folder) == before, "nothing in the folder may be deleted or added"
    assert not default_work.exists()


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_work_folder_loses_exactly_what_its_manifest_lists(shape, tmp_path, small_caps, default_work):
    clip = sent_clip(tmp_path)
    folder = tmp_path / "set-one"
    stub_job(folder, shape, listed=["A.mp4", "B.mp4"], unlisted=["Z.mp4", "Y-photo.jpg"])
    (folder / "look.json").write_bytes(b"{}")
    (folder / "B.part.mp4").write_bytes(b"unfinished")
    (folder / "notes.txt").write_bytes(b"keep")
    kept = {name: sha256(folder / name) for name in ("Z.mp4", "Y-photo.jpg", "notes.txt")}

    assert main(["normalize", "--shape", shape, "--work", str(folder), str(clip)]) == 0

    assert not (folder / "B.mp4").exists() and not (folder / "B.part.mp4").exists()
    assert not (folder / "look.json").exists()
    assert (folder / "A.mp4").read_bytes() != b"old working copy", "A is the new job's own copy"
    assert {name: sha256(folder / name) for name in kept} == kept, "files the manifest does not list must survive"
    assert len(json.loads((folder / "manifest.json").read_text(encoding="utf-8"))["clips"]) == 1


@pytest.mark.parametrize("shape", ["tall", "wide"])
def test_an_empty_work_option_is_refused(shape, tmp_path, monkeypatch, small_caps, default_work, capsys):
    clip = sent_clip(tmp_path)
    monkeypatch.chdir(tmp_path)  # an empty name would otherwise mean this folder
    before = sorted(path.name for path in tmp_path.iterdir())

    assert main(["normalize", "--shape", shape, "--work", "", str(clip)]) == 1

    lines = [line for line in capsys.readouterr().err.splitlines() if line.strip()]
    assert len(lines) == 1 and lines[0].startswith("v2r normalize:") and "--work" in lines[0]
    assert sorted(path.name for path in tmp_path.iterdir()) == before
    assert not default_work.exists()

